def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[y][x] == 2 for y in (r, r + 1) for x in (c, c + 1)):
                blocks.append((r, c))

    for r, c in blocks:
        # Four diagonal cells immediately surrounding each 2x2 block,
        # listed top-left, top-right, bottom-left, bottom-right.
        points = [(r - 1, c - 1), (r - 1, c + 2),
                  (r + 2, c - 1), (r + 2, c + 2)]

        def value(point):
            y, x = point
            return grid[y][x] if 0 <= y < h and 0 <= x < w else 0

        # Cycle the four marker colors around the block, then extend each
        # along the outward diagonal from its corresponding corner.
        colors = [value(points[2]), value(points[0]),
                  value(points[3]), value(points[1])]
        directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        for (y, x), color, (dy, dx) in zip(points, colors, directions):
            if not color or not (0 <= y < h and 0 <= x < w):
                continue
            while 0 <= y < h and 0 <= x < w:
                if grid[y][x] not in (2,) and not (y in range(h) and x in range(w) and any((y, x) in [(br, bc), (br, bc+1), (br+1, bc), (br+1, bc+1)] for br, bc in blocks)):
                    out[y][x] = color
                y += dy
                x += dx
    return out
